output_text:
[
  {
    "id": "no_cart_single_file_aisle",
    "text": "Carts may not be taken into single-file shelf aisles where the horizontal passage is only one cell wide.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "cartInSingleFileShelfAisle": {
          "and": [
            "hasCart",
            "singleFileShelfAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartInSingleFileShelfAisle"
    }
  },
  {
    "id": "no_enter_single_file_with_cart",
    "text": "An agent must not move from a wider aisle into a single-file shelf aisle while still holding a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "park_at_single_file_mouth",
    "text": "On arriving with a cart at the mouth of the single-file shelf aisle, the agent is obliged to park the cart there before continuing.",
    "abstraction": {
      "state_properties": {
        "singleFileMouth": {
          "and": [
            "at(6,3)",
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "arriveAtSingleFileMouthWithCart": {
          "pre": {
            "and": [
              "hasCart",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": "singleFileMouth"
        },
        "dropCartAtSingleFileMouth": {
          "pre": {
            "and": [
              "singleFileMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "arriveAtSingleFileMouthWithCart",
      "discharge": "dropCartAtSingleFileMouth"
    }
  },
  {
    "id": "retrieve_after_single_file",
    "text": "After leaving the single-file shelf aisle without a cart, the agent is obliged to retrieve the parked cart at the aisle mouth.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "singleFileMouth": {
          "and": [
            "at(6,3)",
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "exitSingleFileWithoutCartToMouth": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              {
                "not": "hasCart"
              },
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": "singleFileMouth"
        },
        "pickUpCartAtSingleFileMouth": {
          "pre": {
            "and": [
              "singleFileMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "exitSingleFileWithoutCartToMouth",
      "discharge": "pickUpCartAtSingleFileMouth"
    }
  },
  {
    "id": "cart_required_in_two_wide_bays",
    "text": "Shelf interactions in cart-accessible cramped bays, such as two-wide side aisles or two-deep end aisles, must be performed with the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "twoWideCrampedArea": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            },
            {
              "or": [
                {
                  "and": [
                    {
                      "le": [
                        "freeWidthH",
                        2
                      ]
                    },
                    {
                      "gt": [
                        "freeWidthH",
                        1
                      ]
                    }
                  ]
                },
                {
                  "and": [
                    {
                      "le": [
                        "freeWidthV",
                        2
                      ]
                    },
                    {
                      "gt": [
                        "freeWidthV",
                        1
                      ]
                    }
                  ]
                }
              ]
            }
          ]
        },
        "noCartCrampedShelfInteraction": {
          "and": [
            "twoWideCrampedArea",
            "INTERACT",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "noCartCrampedShelfInteraction"
    }
  },
  {
    "id": "no_drop_cart_in_cramped_bay",
    "text": "The cart must not be parked or dropped inside a cramped shelf bay that is still wide enough for carts.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "cartAccessibleCrampedBay": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            },
            {
              "or": [
                {
                  "and": [
                    {
                      "le": [
                        "freeWidthH",
                        2
                      ]
                    },
                    {
                      "gt": [
                        "freeWidthH",
                        1
                      ]
                    }
                  ]
                },
                {
                  "and": [
                    {
                      "le": [
                        "freeWidthV",
                        2
                      ]
                    },
                    {
                      "gt": [
                        "freeWidthV",
                        1
                      ]
                    }
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartAccessibleCrampedBay",
          "dropCart"
        ]
      }
    }
  },
  {
    "id": "park_only_in_wide_open_aisles",
    "text": "Carts may only be parked in wide open aisle cells, not next to shelves or in narrow shopping bays.",
    "abstraction": {
      "state_properties": {
        "wideOpenAisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "wideOpenAisle"
          }
        ]
      }
    }
  },
  {
    "id": "no_shelf_interact_without_cart_except_single_file",
    "text": "Except in single-file shelf aisles where carts are barred, shelf interactions must not be done without the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "ordinaryShelfAccess": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            }
          ]
        },
        "cartlessOrdinaryShelfInteraction": {
          "and": [
            "ordinaryShelfAccess",
            "INTERACT",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartlessOrdinaryShelfInteraction"
    }
  }
]
